def range_sum_query(nums: list[int], queries: list[list[int]]) -> list[int]:
    prefix = [0] * (len(nums) + 1)
    for i in range(len(nums)):
        prefix[i+1] = prefix[i] + nums[i]
    res = []
    for left, right in queries:
        res.append(prefix[right + 1] - prefix[left])
    return res
